//! Shared by the integration tests: the committed text corpus
//! (`conformance/scenarios/text/corpus/`, generated by
//! `conformance/corpora/text/generate.py`), its goldens, and a seeded
//! generator of awkward field text.

#![allow(dead_code)]

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;

pub fn conformance_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../conformance")
}

/// One `text` request of a corpus scenario with the golden's outputs.
pub struct CorpusRequest {
    pub scenario: String,
    pub fns: Vec<String>,
    pub inputs: Vec<Value>,
    /// The golden's value for this step: `{<function>: [<output>, ...]}`.
    pub expected: Value,
}

/// Every `text` request of every corpus scenario, in file order.
pub fn corpus() -> Vec<CorpusRequest> {
    let dir = conformance_dir().join("scenarios/text/corpus");
    let mut paths: Vec<PathBuf> = fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("{}: {e}", dir.display()))
        .map(|entry| entry.unwrap().path())
        .filter(|path| path.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    let mut requests = Vec::new();
    for path in paths {
        let scenario = read_json(&path);
        let id = scenario["id"].as_str().unwrap().to_owned();
        let golden = read_json(&conformance_dir().join("goldens").join(format!("{id}.json")));
        for (index, step) in scenario["steps"].as_array().unwrap().iter().enumerate() {
            for request in step["observe"].as_array().unwrap() {
                let text = &request["text"];
                requests.push(CorpusRequest {
                    scenario: id.clone(),
                    fns: text["fns"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|f| f.as_str().unwrap().to_owned())
                        .collect(),
                    inputs: text["inputs"].as_array().unwrap().clone(),
                    expected: golden["observations"]["steps"][index]["text"].clone(),
                });
            }
        }
    }
    assert!(!requests.is_empty(), "no corpus under {}", dir.display());
    requests
}

/// The string inputs of the corpus requests that take strings and run
/// `function`.
pub fn corpus_strings(function: &str) -> Vec<String> {
    corpus()
        .into_iter()
        .filter(|r| r.fns.iter().any(|f| f == function))
        .flat_map(|r| r.inputs)
        .filter_map(|v| v.as_str().map(str::to_owned))
        .collect()
}

fn read_json(path: &Path) -> Value {
    let text = fs::read_to_string(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// SplitMix64: a small seeded generator, so a failing case reproduces from
/// its seed.
pub struct Rng(u64);

impl Rng {
    pub fn new(seed: u64) -> Rng {
        Rng(seed)
    }

    pub fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// A value in `0..n`.
    pub fn below(&mut self, n: usize) -> usize {
        (self.next_u64() % n as u64) as usize
    }

    pub fn pick<'a, T>(&mut self, items: &'a [T]) -> &'a T {
        &items[self.below(items.len())]
    }
}

/// Pieces that exercise the patterns: markup openers and closers, quotes,
/// entities, media and sound tags, percent escapes, spacer tags, Unicode
/// whitespace, case-folding letters and multi-byte characters.
const PIECES: &[&str] = &[
    "<",
    ">",
    "\"",
    "'",
    "&",
    ";",
    "=",
    "/",
    " ",
    "\n",
    "\r",
    "\t",
    "\u{a0}",
    "\u{3000}",
    "\u{2028}",
    "\u{85}",
    "a",
    "b",
    "x",
    "é",
    "e\u{301}",
    "日本",
    "😀",
    "\u{17f}",
    "\u{212a}",
    "İ",
    "ß",
    "<b>",
    "</b>",
    "<br>",
    "<BR/>",
    "<br />",
    "<div>",
    "</div>",
    "<div class=c>",
    "<p>",
    "<span></span>",
    "<!--",
    "-->",
    "<style>",
    "</style>",
    "<script>",
    "</script>",
    "<img ",
    "<IMG ",
    "<audio ",
    "<video ",
    "<source ",
    "<object ",
    "<imgx ",
    "src=",
    "SRC=",
    "data=",
    "data-src=",
    "srcset=",
    "alt=",
    "title=",
    "\"a b.png\"",
    "'c.mp3'",
    "d.jpg",
    "a%20b",
    "%e6%97%a5",
    "%",
    "%2",
    "#",
    "`",
    "http://",
    "https://",
    "HTTPS://",
    "[sound:",
    "]",
    "[[type:",
    "]]",
    "&amp;",
    "&lt;",
    "&gt;",
    "&nbsp;",
    "&#32;",
    "&#x41;",
    "&bogus;",
    "&amp",
    "&#;",
    "\u{1}",
    "\u{7f}",
    "?",
    ":",
    "*",
    "|",
    "\\",
    "[",
    "con",
    ".",
    "..",
    "\u{378}",
    "\u{1f970}",
    "\u{e000}",
];

/// A text of up to `max_pieces` random pieces.
pub fn awkward_text(rng: &mut Rng, max_pieces: usize) -> String {
    let n = rng.below(max_pieces + 1);
    (0..n).map(|_| *rng.pick(PIECES)).collect()
}
